# 4 회차 고침 패치 (memo_v3_2.md) · 정확한 문자열 치환 · 개수가 기대와 다르면 아무것도 쓰지 않고 멈춘다
import sys

P = sys.argv[1]
s = open(P, encoding='utf-8').read()
orig = s
log = []


def rep(old, new, n=1):
    global s
    c = s.count(old)
    if c != n:
        raise SystemExit(f'개수 다름 ({c} ≠ {n}): {old[:80]!r}')
    s = s.replace(old, new)
    log.append(f'rep ×{n}: {old[:60]!r}')


def between(start, end, new):
    global s
    if s.count(start) != 1:
        raise SystemExit(f'시작 개수 {s.count(start)}: {start[:60]!r}')
    i = s.index(start)
    j = s.index(end, i)
    if s.count(end) != 1:
        raise SystemExit(f'끝 개수 {s.count(end)}: {end[:60]!r}')
    s = s[:i] + new + s[j + len(end):]
    log.append(f'between: {start[:40]!r} … {end[:40]!r}')


